# Published text of the 28 in-scope AP Physics C: E&M MCQs (24 labelled units 8-10 + 4 held), transcribed from the Production DB.
C={}
def add(k,stem,ch): C['apphycem-mcq-'+k]=(stem,ch)
add('001',"Gauss's law states the electric flux through a closed surface is\n\nA. Q_enclosed/ε₀\nB. ε₀Q_enclosed\nC. Q_total outside/ε₀\nD. always zero",[("A","Q_enclosed/ε₀",1,"closed-surface flux depends on enclosed charge"),("B","ε₀Q_enclosed",0,"This mistakes ε₀ for a multiplier on the enclosed charge rather than the divisor Gauss's law requires."),("C","Q_total outside/ε₀",0,"This confuses charge outside the surface with enclosed charge, which contributes zero net flux."),("D","always zero",0,"This overgeneralizes the special zero-net-enclosed-charge case (or the magnetic-flux identity) into a universal rule.")])
add('002',"For a spherically symmetric volume charge density, the charge enclosed within radius R is…",[("A","∫₀ᴿρ(r)4πr²dr",1,"integrate density over spherical volume elements"),("B","ρ(R)R",0,"This evaluates the density only at the outer radius and scales it linearly by R instead of integrating over the volume."),("C","∫ρ dr only",0,"This drops the 4πr² spherical-shell area factor, treating the volume element as just dr."),("D","4πR²/ρ",0,"This inverts the relationship, dividing a surface area by density instead of integrating density over volume.")])
add('003',"A closed Gaussian surface encloses only a charge-free region of space. The net electric flux through this surface is",[("A","a nonzero constant set by charges outside the surface",0,"Gauss's law in integral form (oint E.dA = q_enc/epsilon_0) depends only on the charge enclosed by the surface; charges outside it contribute zero net flux."),("B","zero",1,"Gauss's law gives oint E.dA = q_enc/epsilon_0, and the enclosed charge q_enc is zero since the region is charge-free."),("C","proportional to the electric field magnitude on the surface",0,"Flux depends on the field's component normal to the surface integrated over the whole closed surface, not simply the field magnitude; a strong field can still give zero net flux when the enclosed charge is zero."),("D","equal to the electric potential difference across the surface",0,"Potential difference relates to work per unit charge along a path (ΔV=-∫E·dl), not to enclosed charge or flux.")])
add('005',"For electrostatics, E is related to V by\n\nA. E=∇V\nB. E=-∇V\nC. E=∇×V\nD. E=∫Vdt",[("A","E=∇V",0,"This drops the negative sign linking the field to the potential gradient."),("B","E=-∇V",1,"the field is the negative potential gradient"),("C","E=∇×V",0,"This misapplies the curl operator to a scalar potential, confusing it with the vector-potential relation B=∇×A."),("D","E=∫Vdt",0,"This substitutes a time integral for the spatial gradient, conflating a static field relation with time dependence.")])
add('006',"A stationary point of V has\n\nA. ∇V=0\nB. V=0 necessarily\nC. infinite charge necessarily\nD. nonzero curl E",[("A","∇V=0",1,"the gradient vanishes at a stationary point"),("B","V=0 necessarily",0,"This confuses a vanishing slope of V with the potential's value itself being zero."),("C","infinite charge necessarily",0,"This assumes a stationary point requires an infinite charge source rather than simply zero gradient."),("D","nonzero curl E",0,"This invokes curl of E, which is always zero for an electrostatic field and unrelated to a stationary point of V.")])
add('007',"Capacitance of parallel plates neglecting edges is\n\nA. εA/d\nB. εd/A\nC. Ad/ε\nD. d/(εA)",[("A","εA/d",1,"C=Q/ΔV=εA/d."),("B","εd/A",0,"This swaps the positions of A and d in the formula."),("C","Ad/ε",0,"This places ε in the denominator and the product of the plate quantities A and d in the numerator, effectively inverting the correct ratio (which has A in the numerator and d in the denominator, with ε multiplying A)."),("D","d/(εA)",0,"This takes the reciprocal of the correct capacitance expression.")])
add('008',"Energy stored in a capacitor is\n\nA. CV²\nB. CV²/2\nC. C/V²\nD. 2C/V",[("A","CV²",0,"This drops the factor of one-half that comes from integrating V dq up to charge Q."),("B","CV²/2",1,"integrating V dq gives one-half CV²"),("C","C/V²",0,"This divides by V² instead of multiplying, inverting the voltage dependence."),("D","2C/V",0,"This misplaces the factor of 2 as a coefficient of C divided by V rather than one-half CV².")])
add('009',"In electrostatic equilibrium, within the conducting material of a conductor, E is\n\nA. maximum\nB. zero\nC. nonzero but uniform throughout\nD. time varying",[("A","maximum",0,"This reverses the actual physics, assuming free charge concentrates the field rather than canceling it in equilibrium."),("B","zero",1,"Free charges rearrange until the field within the conducting material vanishes."),("C","nonzero but uniform throughout",0,"This mistakes electrostatic equilibrium for merely uniform field conditions; equilibrium in a conductor specifically requires E to vanish everywhere within the conducting material, not merely be constant."),("D","time varying",0,"This assumes electrostatic equilibrium implies an oscillating field rather than a static zero field.")])
add('016',"Faraday's law in integral form states that the emf around a closed loop, the line integral of E around the loop, is equal to--\n\nA. dΦ_B/dt\nB. -dΦ_B/dt\nC. -Φ_B/t\nD. -μ₀I_enc",[("A","dΦ_B/dt",0,"This drops the negative sign that encodes Lenz's law in Faraday's law."),("B","-dΦ_B/dt",1,"the minus sign encodes Lenz's law"),("C","-Φ_B/t",0,"This treats the rate of change as a simple ratio of flux to elapsed time rather than the true time derivative -- Φ_B/t equals dΦ_B/dt only in the special case where flux grows linearly from zero."),("D","-μ₀I_enc",0,"This is (the negative of) the right-hand side of Ampere's law, a different circulation law relating B to enclosed current -- a cross-law confusion, not a Faraday's-law expression.")])
add('019',"For a point charge, ∇·E is zero everywhere except at the charge's location, where the ordinary field expression is singular and its divergence must be understood in the distributional sense (as a Dirac delta function), not as an ordinary finite value. Where is this exception located?\n\nA. at infinity\nB. at the charge location\nC. on every sphere\nD. along one axis",[("A","at infinity",0,"This misplaces the singularity from the charge's actual location out to spatial infinity."),("B","at the charge location",1,"The source is represented by a Dirac delta distribution located at the charge -- this is where the divergence is nonzero in the distributional sense, distinct from nonzero flux through a surface (which reflects enclosed charge, not divergence at points on the surface)."),("C","on every sphere",0,"This extends the singular divergence to every enclosing sphere; nonzero flux through a sphere enclosing the charge reflects the enclosed charge, not a nonzero divergence at points on that sphere."),("D","along one axis",0,"This assumes the divergence is undefined along an entire line rather than at the single point of the charge.")])
add('021',"Two point charges remain fixed while their separation triples. The force magnitude becomes\n\nA. three times\nB. one-third\nC. one-ninth\nD. one-twenty-seventh",[("A","three times",0,"This applies direct rather than inverse distance scaling."),("B","one-third",0,"This uses inverse-linear scaling and misses the square."),("C","one-ninth",1,"Coulomb force varies as 1/r², so tripling r divides force by nine."),("D","one-twenty-seventh",0,"This incorrectly uses an inverse-cube relation.")])
add('022',"The electric field due to an isolated negative point charge points\n\nA. radially outward\nB. radially inward\nC. tangent to circles\nD. its direction depends on the sign of the test charge",[("A","radially outward",0,"This is the direction for a positive source charge."),("B","radially inward",1,"The field points in the force direction on a positive test charge, toward a negative source."),("C","tangent to circles",0,"This confuses electric point-charge geometry with magnetic field around a current."),("D","its direction depends on the sign of the test charge",0,"Electric-field direction is a property of the source charge and does not depend on the sign of a test charge.")])
add('023',"For a line charge λ(s), the differential charge element is\n\nA. λ ds\nB. λ dA\nC. λ dV\nD. (dλ/ds)ds",[("A","λ ds",1,"Linear density times differential length gives dq=λ ds."),("B","λ dA",0,"This uses an area element appropriate to surface charge density."),("C","λ dV",0,"This uses a volume element appropriate to volume charge density."),("D","(dλ/ds)ds",0,"The linear charge density already gives charge per unit length, so dq = λ(s)ds; differentiating λ is not required.")])
add('024',"Uniform E crosses flat area A whose normal makes angle θ with E. Electric flux is\n\nA. EA sinθ\nB. EA cosθ\nC. EA/ cosθ\nD. EA",[("A","EA sinθ",0,"This uses the angle with the surface rather than the stated angle with its normal."),("B","EA cosθ",1,"Flux is the dot product EA cosθ using the surface normal."),("C","EA/ cosθ",0,"This divides by the projection factor instead of multiplying."),("D","EA",0,"This ignores the angle between the electric field and the surface normal; only the normal component contributes to flux.")])
add('025',"Charges outside a closed Gaussian surface contribute to\n\nA. net enclosed charge\nB. local field but zero net flux contribution\nC. neither field nor flux anywhere\nD. nonzero net flux but no enclosed charge",[("A","net enclosed charge",0,"This incorrectly counts external charge as enclosed."),("B","local field but zero net flux contribution",1,"External charges can affect E locally, but their field lines enter and leave with zero net closed-surface flux."),("C","neither field nor flux anywhere",0,"This ignores the electric field from external sources."),("D","nonzero net flux but no enclosed charge",0,"An external charge's field lines enter and leave a closed surface with zero net flux contribution.")])
add('026',"Two positive point charges are brought closer together. Their electric potential energy\n\nA. decreases\nB. increases\nC. stays zero\nD. becomes negative",[("A","decreases",0,"This reverses the inverse-distance dependence for positive U."),("B","increases",1,"For like charges U=kq₁q₂/r is positive and increases as separation decreases."),("C","stays zero",0,"This assumes a zero reference means all separations have zero energy."),("D","becomes negative",0,"Negative potential energy applies to opposite-sign charges.")])
add('027',"With V(∞)=0, point-charge potential is\n\nA. kq/r\nB. kq/r²\nC. kq/(2r)\nD. -kq/r",[("A","kq/r",1,"Integrating the point-charge field from infinity gives V=kq/r."),("B","kq/r²",0,"This confuses potential with electric-field magnitude."),("C","kq/(2r)",0,"This incorrectly introduces a factor of one-half from energy formulas."),("D","-kq/r",0,"This incorrectly retains a negative sign; the potential is kq/r and its sign is determined by q.")])
add('028',"A positive charge is released from rest and acted on only by a static electric field. It tends toward\n\nA. higher potential and higher U\nB. lower potential and lower U\nC. higher potential and lower U\nD. unchanged kinetic energy always",[("A","higher potential and higher U",0,"This sends the charge uphill in potential energy without external work."),("B","lower potential and lower U",1,"For q>0, U=qV, so electric force accelerates it toward lower V and lower U."),("C","higher potential and lower U",0,"For positive charge, higher V means higher, not lower, potential energy."),("D","unchanged kinetic energy always",0,"A potential-energy decrease generally appears as increased kinetic energy.")])
add('029',"In electrostatic equilibrium, the electric field just outside a conductor is\n\nA. tangent to the surface\nB. normal to the surface\nC. zero for every charged conductor\nD. parallel to surface current",[("A","tangent to the surface",0,"This would drive free charges along the surface and violate equilibrium."),("B","normal to the surface",1,"Any tangential field would move surface charge, so equilibrium field is normal."),("C","zero for every charged conductor",0,"Interior field is zero, but exterior normal field can be nonzero."),("D","parallel to surface current",0,"Electrostatic equilibrium has no sustained surface current.")])
add('030',"A dielectric with κ>1 fully fills a capacitor that remains connected to an ideal battery. Stored energy\n\nA. becomes 1/κ as large\nB. is unchanged\nC. becomes κ times as large\nD. increases by κ²",[("A","becomes 1/κ as large",0,"This uses the fixed-charge result instead of the fixed-voltage condition."),("B","is unchanged",0,"This ignores the capacitance increase while voltage is held fixed."),("C","becomes κ times as large",1,"At fixed V, C increases by κ and U=(1/2)CV² increases by κ."),("D","increases by κ²",0,"The ideal battery keeps voltage fixed, so only capacitance increases by κ and stored energy increases by κ, not κ².")])
add('np1-001',"An infinitely long, uniformly charged wire has linear charge density lambda > 0. Using Gauss's law with a cylindrical Gaussian surface of length L, which expression correctly gives the electric field magnitude at a perpendicular distance r from the wire?",[("A","lambda/(2*pi*epsilon_0*r)",1,"The Gaussian surface's curved lateral area is 2*pi*r*L, and the enclosed charge is lambda*L; solving E*(2*pi*r*L)=lambda*L/epsilon_0 gives E=lambda/(2*pi*epsilon_0*r)."),("B","lambda/(4*pi*epsilon_0*r^2)",0,"This is the point-charge (spherical symmetry) form of Coulomb's law, misapplied to a cylindrically symmetric charge distribution -- a documented error of using the wrong symmetry's formula."),("C","lambda*L/(2*pi*epsilon_0*r)",0,"This fails to cancel the L that appears in both the enclosed charge and the Gaussian surface area."),("D","lambda/(pi*epsilon_0*r^2)",0,"This uses an incorrect Gaussian surface area (resembling a disk, pi*r^2, rather than the correct cylindrical lateral area 2*pi*r*L).")])
add('np1-002',"A thin spherical shell of radius R carries total charge +Q uniformly distributed on its surface. Using a spherical Gaussian surface of radius r, where r > R, what is the correct enclosed charge q_enc to use in Gauss's law?",[("A","Q",1,"Since r > R, the entire charged shell (all of charge Q, physically located at radius R) lies inside the Gaussian surface, regardless of how much larger r is than R."),("B","Q*(r/R)",0,"This incorrectly scales the enclosed charge with the Gaussian surface's radius, as though charge were spread out to fill the larger radius -- a documented misconception."),("C","Q*(R/r)",0,"This incorrectly scales the enclosed charge inversely with the Gaussian radius; the physical charge does not change based on where the imaginary Gaussian surface is drawn."),("D","0",0,"This incorrectly assumes no charge is enclosed, but the shell's charge lies entirely within any Gaussian surface of radius r > R.")])
add('np1-003',"In a region of space, the electric potential decreases as x increases (dV/dx < 0 everywhere in this region). What can be concluded about the electric field component E_x in this region?",[("A","E_x is positive (the field points in the +x direction)",1,"Since E_x = -dV/dx, and dV/dx is negative, E_x = -(negative) = positive."),("B","E_x is negative (the field points in the -x direction)",0,"This drops the negative sign in E_x=-dV/dx, incorrectly keeping the same sign as dV/dx instead of flipping it."),("C","E_x is zero",0,"A nonzero (negative) spatial rate of change in potential corresponds to a nonzero field component, not zero."),("D","E_x cannot be determined without more information",0,"The relationship E_x=-dV/dx directly determines the sign of E_x from the sign of dV/dx alone.")])
add('np1-004',"A charge +Q is fixed at one location, and a charge -Q of equal magnitude is fixed a distance away. At the midpoint between them, which statement is correct? (Use the standard convention V=0 at infinity.)",[("A","The electric field is nonzero, but the electric potential is zero",1,"At the midpoint, both charges' field contributions point in the same direction (from + toward -) and add, giving a nonzero field; but the potential contributions are equal in magnitude and opposite in sign (+kQ/r and -kQ/r), summing to exactly zero."),("B","The electric field is zero, but the electric potential is nonzero",0,"This reverses the correct result -- the field components add (same direction) rather than cancel, and the potential terms cancel (opposite signs) rather than add."),("C","Both the electric field and electric potential are zero",0,"The field does not cancel here, since both contributions point in the same direction at the midpoint."),("D","Both the electric field and electric potential are nonzero",0,"The potential does cancel exactly, since the two equal-and-opposite charges are equidistant from the midpoint.")])
add('np1-005',"A cylindrical capacitor consists of two coaxial conducting cylinders of length L, inner radius a and outer radius b. A dielectric of constant kappa completely fills the space between them. Which expression correctly gives the capacitance? Assume the cylinders are long enough that end effects are negligible.",[("A","2*pi*kappa*epsilon_0*L / ln(b/a)",1,"Deriving C=Q/deltaV from this cylindrical geometry's actual field and potential-difference expressions gives this result."),("B","kappa*epsilon_0*A/d",0,"This is the parallel-plate capacitance formula, applied incorrectly to a cylindrical geometry -- a real, officially documented high-frequency error (this geometry has neither a well-defined plate area A nor a uniform separation d)."),("C","4*pi*kappa*epsilon_0*a*b / (b-a)",0,"This is the capacitance formula for a concentric SPHERICAL capacitor, not a coaxial cylindrical one -- a plausible confusion between the two non-planar geometries in scope for this course."),("D","kappa*epsilon_0 / (b-a)",0,"This expression is dimensionally inconsistent with capacitance and does not correspond to either correct non-planar geometry.")])
add('np1-006',"A solid insulating sphere of radius R has uniform volume charge density rho. What is the electric field magnitude at a distance r = R/2 from the center (inside the sphere)?",[("A","rho*R/(6*epsilon_0)",1,"Inside a uniformly charged sphere, E(r)=rho*r/(3*epsilon_0). At r=R/2, this gives rho*(R/2)/(3*epsilon_0)=rho*R/(6*epsilon_0)."),("B","rho*R/(3*epsilon_0)",0,"This uses r=R (the surface value) instead of the requested interior point r=R/2."),("C","rho*R/(12*epsilon_0)",0,"This introduces an extra factor-of-2 error beyond the correct substitution of r=R/2."),("D","rho*R/(2*epsilon_0)",0,"Incorrect. Conflates the volume-charge sphere formula with the infinite-sheet-of-charge formula E=sigma/(2*epsilon_0), substituting sigma=rho*R: rho*R/(2*epsilon_0).")])
add('np1-009',"A charged conductor is in electrostatic equilibrium. Which statement correctly describes the electric field at a point just inside the conductor's surface, and at a point just outside its surface? (Assume the point in question lies on a region of the surface where the local surface charge density is nonzero.)",[("A","Zero just inside; nonzero and perpendicular to the surface just outside",1,"In electrostatic equilibrium, the field inside a conductor is always zero, and just outside a charged conductor's surface the field is nonzero and perpendicular to the surface."),("B","Nonzero just inside; zero just outside",0,"This reverses the correct relationship -- the field is zero inside a conductor in equilibrium, not outside it."),("C","Zero at both locations",0,"The field just outside a charged conductor's surface is nonzero."),("D","Nonzero and parallel to the surface at both locations",0,"The field inside a conductor in equilibrium is zero, not nonzero and parallel to the surface.")])
add('np1-010',"A point charge +Q sits at the exact center of a cubical Gaussian surface. What is the electric flux through one face of the cube?",[("A","Q/(6*epsilon_0)",1,"By Gauss's law the total flux through the cube is Q/epsilon_0; by symmetry, the six identical faces each receive an equal share, giving Q/(6*epsilon_0) per face."),("B","Q/epsilon_0",0,"This is the TOTAL flux through the entire cube, not the flux through just one face."),("C","Q/(4*pi*epsilon_0)",0,"This resembles the structure of the point-charge field formula, not a flux calculation."),("D","Q/(24*epsilon_0)",0,"This divides by an incorrect number of faces (24 instead of 6).")])
